<script lang="ts">
  import { facade } from '../bus/gameFacade.js';
  import { game } from '../../gameManager.js';
  import {
    PROF_CHEN_DEFAULT_TOPIC_ID,
    PROF_CHEN_TOPICS,
    type ProfChenLocale,
    type ProfChenTopic,
    type ProfChenTopicId,
  } from '../data/profChenWikiContent.ts';
  import { uiText } from '../ui/i18n.ts';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';

  const { trackGameLanguage } = useGameLanguageTick();

  function resolveLocale(): ProfChenLocale {
    trackGameLanguage();
    const normalized = game && typeof game.normalizeLanguage === 'function'
      ? game.normalizeLanguage(game.language)
      : String(game?.language || 'fr').toLowerCase();
    return normalized.startsWith('en') ? 'en' : 'fr';
  }

  function modalT(key: string, fallback: string): string {
    trackGameLanguage();
    return uiText(key, fallback, {}, game);
  }

  function findTopic(topicId: string): ProfChenTopic {
    return PROF_CHEN_TOPICS.find((topic) => topic.id === topicId) ?? PROF_CHEN_TOPICS[0];
  }

  const initialTopic = findTopic(PROF_CHEN_DEFAULT_TOPIC_ID);
  let selectedTopicId = $state<ProfChenTopicId>(initialTopic.id as ProfChenTopicId);
  let openFaqId = $state(initialTopic.faqs[0]?.id ?? '');

  let locale = $derived(resolveLocale());
  let titleLabel = $derived(modalT('modal.profChenTitle', 'Les conseils du Prof Chen'));
  let introLabel = $derived(modalT('modal.profChenIntro', 'Hey Prof Chen, je veux en savoir plus sur'));
  let closeLabel = $derived(modalT('modal.profChenClose', 'Fermer les conseils'));
  let selectedTopic = $derived(findTopic(selectedTopicId));

  function closeModal() {
    facade.dispatch({ type: 'CLOSE_MODAL', modalId: 'profChenWikiModal' });
  }

  function onTopicChange(e: Event) {
    const nextId = (e.target as HTMLSelectElement).value;
    const nextTopic = findTopic(nextId);
    selectedTopicId = nextTopic.id as ProfChenTopicId;
    openFaqId = nextTopic.faqs[0]?.id ?? '';
  }

  function toggleFaq(faqId: string) {
    openFaqId = openFaqId === faqId ? '' : faqId;
  }
</script>

<div
  class="stats-content js-modal-content farming-metrics-modal-content prof-chen-modal-shell"
  data-action="stopPropagation"
  data-action-stop
>
  <div class="stats-header prof-chen-modal-header">
    <div class="prof-chen-title-wrap">
      <img
        src="img/prof_chen.png"
        class="prof-chen-title-sprite"
        alt=""
        aria-hidden="true"
        decoding="async"
      >
      <h2 id="profChenWikiTitleLabel">{titleLabel}</h2>
    </div>
    <button
      type="button"
      class="stats-close"
      data-action="closeProfChenWikiModal"
      title={closeLabel}
      aria-label={closeLabel}
    >&#10005;</button>
  </div>

  <div class="farming-metrics-body prof-chen-modal-body">
    <label class="prof-chen-question-row" for="profChenWikiTopicSelect">
      <span>{introLabel}</span>
      <select
        id="profChenWikiTopicSelect"
        class="prof-chen-topic-select"
        value={selectedTopicId}
        onchange={onTopicChange}
      >
        {#each PROF_CHEN_TOPICS as topic (topic.id)}
          <option value={topic.id}>{topic.label[locale]}</option>
        {/each}
      </select>
    </label>

    <section
      id="profChenWikiPanel"
      class="prof-chen-faq-list"
      data-prof-chen-panel
      data-topic-id={selectedTopic.id}
      aria-live="polite"
    >
      {#each selectedTopic.faqs as faq (faq.id)}
        {@const isOpen = openFaqId === faq.id}
        <article class="prof-chen-faq-item" class:prof-chen-faq-item-open={isOpen}>
          <button
            type="button"
            class="prof-chen-faq-question"
            aria-expanded={isOpen}
            aria-controls={`profChenFaqAnswer-${faq.id}`}
            data-prof-chen-question
            onclick={() => toggleFaq(faq.id)}
          >
            <span>{faq.question[locale]}</span>
            <span class="prof-chen-faq-chevron" aria-hidden="true">{isOpen ? '-' : '+'}</span>
          </button>
          {#if isOpen}
            <p
              id={`profChenFaqAnswer-${faq.id}`}
              class="prof-chen-faq-answer"
              data-prof-chen-answer
            >{faq.answer[locale]}</p>
          {/if}
        </article>
      {/each}
    </section>
  </div>
</div>
